"""Generate an exact callable inventory from source, with real line anchors.

The prose walkthrough covers the mathematical execution; this inventory
prevents a tutor from relying on invented or stale symbol names.
"""

import ast
from pathlib import Path


def main():
    root = Path(__file__).resolve().parents[1]
    lines = [
        "# Source callable reference",
        "",
        "Generated by `python scripts/generate_code_reference.py`. Read with",
        "`PROJECT_CODE_WALKTHROUGH.md` for inputs, outputs, tensor shapes,",
        "algorithm steps, mathematical reasoning and associated tests.",
        "",
    ]
    for path in sorted((root / "src/lowrank_lab").rglob("*.py")):
        tree = ast.parse(path.read_text(encoding="utf-8"))
        functions = []

        def visit(node, prefix=""):
            for child in ast.iter_child_nodes(node):
                if isinstance(child, ast.ClassDef):
                    visit(child, prefix + child.name + ".")
                elif isinstance(child, (ast.FunctionDef, ast.AsyncFunctionDef)):
                    functions.append((prefix + child.name, child))

        visit(tree)
        if not functions:
            continue
        rel = path.relative_to(root).as_posix()
        lines += [f"## {rel}", ""]
        for name, node in functions:
            args = ast.unparse(node.args)
            description = ast.get_docstring(node)
            lines += [f"### `{name}({args})`", "", f"Source line: {node.lineno}.", ""]
            if description:
                lines += [description, ""]
            else:
                lines += ["See the module's execution section in PROJECT_CODE_WALKTHROUGH.md.", ""]
    (root / "learning/CODE_REFERENCE.md").write_text("\n".join(lines), encoding="utf-8")


if __name__ == "__main__":
    main()
